mapper.select:
select A.FINPROD_ID code, NVL(A.FINPROD_ABBR, A.FINPROD_NAME) shortName, A.FINPROD_NAME "name" from FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID
A.P_FINPROD_ID IS NULL AND B.ISSUE_STATUS = #{ISSUE_STATUS01}
and (instr(A.FINPROD_ID, #{param}) > 0 or instr(A.FINPROD_NAME, #{param}) > 0 or instr(A.FINPROD_ABBR, #{param}) > 0)

		SELECT distinct
        	SYS_USER.USER_NAME as id, 
        	SYS_USER.REAL_NAME as text
        	/*多级法人改造    add bu caojin 2020/6/20   start*/
        	,SYS_DEPARTMENT.INSTITUTION_CODE institution
        	/*多级法人改造    add bu caojin 2020/6/20   end*/
        FROM
          	SYS_USER
        INNER JOIN SYS_USER_ROLE ON SYS_USER.USER_NAME = SYS_USER_ROLE.USER_ID
        INNER JOIN SYS_ROLE ON SYS_ROLE.ROLE_ID = SYS_USER_ROLE.ROLE_ID

        	AND SYS_ROLE.ROLE_POS = #{roleName,jdbcType=VARCHAR}

		/*多级法人改造    add bu caojin 2020/6/20   start*/
	   left join  SYS_DEPARTMENT 
	   ON SYS_USER.DEPT_CODE = SYS_DEPARTMENT.DEPT_CODE
	   /*多级法人改造    add bu caojin 2020/6/20   end*/


   		where 1=1  

        	AND   (SYS_USER.USER_NAME like concat(concat('%',#{search}),'%') 
        	or SYS_USER.REAL_NAME like concat(concat('%',#{search}),'%') )


   			and SYS_USER.USER_NAME = #{initValue}

SELECT distinct SYS_USER.USER_NAME as id, SYS_USER.REAL_NAME as text FROM SYS_USER INNER JOIN SYS_USER_ROLE ON SYS_USER.USER_NAME = SYS_USER_ROLE.USER_ID INNER JOIN SYS_ROLE ON SYS_ROLE.ROLE_ID = SYS_USER_ROLE.ROLE_ID
AND SYS_ROLE.ROLE_POS = #{roleName,jdbcType=VARCHAR}
INNER JOIN SYS_DEPARTMENT ON SYS_USER.DEPT_CODE = SYS_DEPARTMENT.DEPT_CODE AND SYS_DEPARTMENT.INSTITUTION_CODE = #{institution}
where 1=1
AND (SYS_USER.USER_NAME like concat(concat('%',#{search}),'%') or SYS_USER.REAL_NAME like concat(concat('%',#{search}),'%') )
and SYS_USER.USER_NAME = #{initValue}

SELECT distinct SYS_USER.USER_NAME as id, SYS_USER.REAL_NAME as text FROM SYS_USER where 1=1
AND (SYS_USER.USER_NAME like concat(concat('%',#{search}),'%') or SYS_USER.REAL_NAME like concat(concat('%',#{search}),'%') )
and SYS_USER.USER_NAME = #{initValue}

SELECT CUSTOMER_ID id, CUSTOMER_NAME text FROM MST_CUSTOMER_INFO where 1=1
and MST_CUSTOMER_INFO.CUSTOMER_TYPE in
#{item}
AND (CUSTOMER_ID like concat(concat('%',#{search}),'%') or CUSTOMER_NAME like concat(concat('%',#{search}),'%') )
and CUSTOMER_ID = #{initValue}

    	select  COUNTER_ID id,
    			COUNTER_NAME text
    	from MST_COUNTER_PARTY
    	where COUNTER_TYPE = #{counterType}

   			and (COUNTER_ID like concat(concat('%',#{search}),'%')
   			or COUNTER_NAME like concat(concat('%',#{search}),'%'))


		and(COUNTER_ID = #{initValue} 
			or COUNTER_ID in

	           	#{item}

        )

select CALENDAR_ID id, CALENDAR_NAME text from MST_CALENDAR_INFO
and (CALENDAR_ID like concat(concat('%',#{search}),'%') or CALENDAR_NAME like concat(concat('%',#{search}),'%'))
and CALENDAR_ID = #{initValue}

		select FIN_PRODUCT.FINPROD_ID id, FINPROD_MARKET_ID || ':' || FINPROD_ABBR text
		from FIN_PRODUCT, FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY
		where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
		  and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeProd}
		  and FIN_PRODUCT.P_FINPROD_ID IS NULL

		  	and FIN_PRODUCT_ADD.ISSUE_STATUS = #{issueStatus}


		  and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID


			and (FIN_PRODUCT.FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
    			or FIN_PRODUCT.FINPROD_ABBR like concat(concat('%',#{search}),'%'))


			and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}



         		and FIN_PRODUCT.FINPROD_ID = #{initValue}

select FEE_ID id, FEE_ID || ':' || FEE_NAME text from MST_FEEINFO where APPLY_TYPE = #{relationProd}
and (FEE_ID like concat(concat('%', #{search}), '%') or FEE_NAME like concat(concat('%', #{search}), '%'))
and FEE_ID IN (#{initValue})

select count(1) from WFL_TRD_PRODUCT_DEAL 
where TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR}

select count(1) from TRD_PRODUCT_DEAL 
where 
    (TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR})
    and 
    (IS_CANCEL = #{YES_NO_YES,jdbcType=VARCHAR}
    or TRADE_STATUS = #{TRADE_STATUS_03,jdbcType=VARCHAR}
    )

select 
from PA_BRANCH_SALE_DETAIL
where TRADE_ID = #{tradeId}

		select 

        from TRD_FIN_PRODUCT_DEAL_TOTAL
        where 1=1

            and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


            and PS = #{ps,jdbcType=VARCHAR}


            and TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR}


            and TRADE_DATE = #{tradeDate,jdbcType=DATE}


            and SETTLE_DATE = #{settleDate,jdbcType=DATE}


            and TOTLE_TRADE_ID = #{totleTradeId,jdbcType=VARCHAR}


		select 

        from prd_mdate_adjust
        where 1=1

            and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


            and ADJUST_NUM = #{adjustNum,jdbcType=INTEGER}


            and ADJUST_TYPE = #{adjustType,jdbcType=VARCHAR}

select rep.REP_FINPROD_INS_ID id, rep.REP_FINPROD_INS_ID text, rep.REP_FINPROD_ID finprodId from REP_PROD_DECLARE rep where not EXISTS ( select fin.FINPROD_ID from FIN_PRODUCT fin where rep.REP_FINPROD_ID = fin.FINPROD_ID
AND rep.REP_FINPROD_INS_ID != #{repFinprodInsId,jdbcType=VARCHAR}
) and not EXISTS ( select issue.REP_BANK_PROD_CODE from REP_PROD_ISSUE issue where rep.REP_FINPROD_INS_ID = issue.REP_BANK_PROD_CODE
AND rep.REP_FINPROD_INS_ID != #{repFinprodInsId,jdbcType=VARCHAR}
)
AND (rep.REP_FINPROD_INS_ID like concat(concat('%',#{search}),'%') or rep.REP_FINPROD_NAME like concat(concat('%',#{search}),'%') )
AND rep. rep_operate_mode in (#{repoperatemode02},#{repoperatemode04})
AND rep. rep_operate_mode in (#{repoperatemode01},#{repoperatemode03})

