mapper.select:
SELECT
prd_layer_param.finprod_id as id, prd_layer_param.prod_style as text
prd_layer_param.prod_style as id, prd_layer_param.prod_style as text, prd_layer_param.finprod_id as object
fin_product.finprod_abbr as id, prd_layer_param.prod_style as text, prd_layer_param.finprod_id as object
FROM prd_layer_param inner join fin_product on prd_layer_param.finprod_id = fin_product.finprod_id where 1=1
AND (prd_layer_param.finprod_id like concat(concat('%',#{search}),'%') or prd_layer_param.prod_style like concat(concat('%',#{search}),'%') )
AND prd_layer_param.prod_style like concat(concat('%',#{search}),'%')
AND (fin_product.finprod_abbr like concat(concat('%',#{search}),'%') or prd_layer_param.prod_style like concat(concat('%',#{search}),'%') )
and prd_layer_param.finprod_id = #{initValue}
and prd_layer_param.prod_style = #{initValue}
and fin_product.finprod_abbr = #{initValue}
and prd_layer_param.p_finprod_id in
#{item}
and fin_product.finprod_market_id = #{finprodMarketId}
and prd_layer_param.p_finprod_id = #{finprodId}
